import * as Haptics from 'expo-haptics';
import { AudioPlayer, createAudioPlayer } from 'expo-audio';

/**
 * Sound and vibration: the two things the game does to the device rather than
 * the screen. Both are best-effort — an effect that cannot play is skipped,
 * never thrown — and both obey the player's settings, which the app pushes in
 * here whenever they change so that callers need not carry them around.
 */

export type Sound = 'throw' | 'keep' | 'score' | 'zero' | 'bonus' | 'win';

// Generated by scripts/make-sounds.js.
const SOURCES: Record<Sound, number> = {
  throw: require('../assets/sounds/throw.wav'),
  keep: require('../assets/sounds/keep.wav'),
  score: require('../assets/sounds/score.wav'),
  zero: require('../assets/sounds/zero.wav'),
  bonus: require('../assets/sounds/bonus.wav'),
  win: require('../assets/sounds/win.wav'),
};

const enabled = { sound: true, haptics: true };

export const configureFeedback = (settings: { sound: boolean; haptics: boolean }): void => {
  enabled.sound = settings.sound;
  enabled.haptics = settings.haptics;
};

// Players are made on first use and then kept: creating one decodes the file,
// which is too slow to do on the beat of a dice throw.
const players: Partial<Record<Sound, AudioPlayer>> = {};

export const play = (sound: Sound): void => {
  if (!enabled.sound) return;
  try {
    const player = (players[sound] ??= createAudioPlayer(SOURCES[sound]));
    // Rewind first, so a sound still ringing from last time starts over.
    void Promise.resolve(player.seekTo(0)).catch(() => {});
    player.play();
  } catch {
    // No audio on this device, or the browser has not been tapped yet.
  }
};

export const hapticTap = (style: Haptics.ImpactFeedbackStyle): void => {
  if (!enabled.haptics) return;
  Haptics.impactAsync(style).catch(() => {});
};

export const hapticNotify = (type: Haptics.NotificationFeedbackType): void => {
  if (!enabled.haptics) return;
  Haptics.notificationAsync(type).catch(() => {});
};
